{
  "name": "@cipher208/opencode-doc-select",
  "version": "0.1.0",
  "description": "OpenCode plugin: open a file in a tmux pane and read back the text the user selected with the mouse.",
  "type": "module",
  "main": "src/plugin.ts",
  "exports": {
    ".": "./src/plugin.ts"
  },
  "files": [
    "src",
    "README.md",
    "LICENSE",
    "CHANGELOG.md"
  ],
  "scripts": {
    "test": "bun test",
    "typecheck": "tsc --noEmit"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "tmux",
    "terminal",
    "mouse",
    "typescript",
    "bun"
  ],
  "license": "MIT",
  "peerDependencies": {
    "@opencode/plugin": ">=2.2.7"
  },
  "devDependencies": {
    "@opencode/plugin": "2.2.7",
    "@types/bun": "^1.4.2",
    "typescript": "^5.9.3"
  },
  "author": "Cipher208",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/Cipher208/opencode-doc-select.git"
  },
  "homepage": "https://github.com/Cipher208/opencode-doc-select#readme",
  "bugs": {
    "url": "https://github.com/Cipher208/opencode-doc-select/issues"
  },
  "publishConfig": {
    "access": "public"
  }
}
